message.content:
{
  "action": "send",
  "subject": "HN casings – renewal options",
  "body": "Dear Mr Brandlhuber,\n\nThank you for your offer and our valued partnership. We want a renewal that supports dependable supply and sustainable pricing.\n\n[[c3]] Please reflect this offset in the adjustment.\n[[c9]] Please also consider the benefit of our planned demand.\n\nCould you share a cost bridge separating material, energy, labour, overhead and margin, including their respective weights?\n\nWe propose three alternatives:\nA: €130.00, effective 1 January 2027, payment 60 days.\nB: €129.20, effective 1 January 2027, payment 14 days, offering faster cash in exchange for a lower price.\nC: €131.00, effective 1 April 2027, payment 30 days, offering a higher price in exchange for later implementation.\n\nAll retain the enquiry’s fixed terms. Which package best suits your business?\n\nKind regards,\nHollerau Pumpenwerke, Purchasing",
  "term_sheets": [
    {
      "unit_price": 130.0,
      "effective_date": "2027-01-01",
      "payment_days": 60
    },
    {
      "unit_price": 129.2,
      "effective_date": "2027-01-01",
      "payment_days": 14
    },
    {
      "unit_price": 131.0,
      "effective_date": "2027-04-01",
      "payment_days": 30
    }
  ],
  "rationale": "Their justification covers selected cost increases but does not explain the full adjustment; the energy offset and growing demand support a lower opening counter. Distinct payment and implementation packages test their apparent interest in cash and continuity without treating the uncertain cost estimate as established fact.",
  "target_price": 130.0
}

