message.content:
{
  "action": "send",
  "subject": "HN casings – cash-payment package",
  "body": "Dear Mr Brandlhuber,\n\nThank you for the meaningful adjustment. We respect the confidentiality of your internal calculations and appreciate your willingness to recognise the offsets.\n\nFaster payment is a tangible benefit we can offer. If you retain the January implementation date and agree to €130.40 per unit, we can commit to payment within 14 days rather than seek longer terms.\n\nAlternatively, if you can defer implementation until 1 April 2027, we can move to €131.40 while retaining 14-day payment. Existing pricing would remain until implementation.\n\nBoth packages retain the fixed enquiry terms. Please consider which combination provides the better balance for your cash flow and production planning.\n\nKind regards,\nHollerau Pumpenwerke, Purchasing",
  "term_sheets": [
    {
      "unit_price": 130.4,
      "effective_date": "2027-01-01",
      "payment_days": 14
    },
    {
      "unit_price": 131.4,
      "effective_date": "2027-04-01",
      "payment_days": 14
    }
  ],
  "rationale": "Their substantial reduction and explicit preference for 14-day payment identify cash flow as the strongest lever. A modest conditional price increase tests further room, while a later implementation package exchanges a higher nominal price for continued existing pricing.",
  "target_price": 130.4
}

