{
  "action": "send",
  "subject": "HN casings – April implementation package",
  "body": "Dear Mr Brandlhuber,\n\nThank you for accommodating April implementation and for sharing the delivery schedule. That transition would help us reach a balanced renewal.\n\nIf you confirm implementation on 1 April 2027 with existing pricing maintained beforehand, we can raise our April proposal to €132.00 per unit and retain 14-day payment.\n\nAlternatively, for January implementation with 14-day payment, we can move to €131.25 per unit. All fixed enquiry terms remain unchanged.\n\nOur preference is the April package. Please also reconcile the schedule’s monthly rounding to the agreed annual quantity; the final month can absorb the adjustment.\n\nCould you take a further step on the April price in return for our continued fast payment?\n\nKind regards,\nHollerau Pumpenwerke, Purchasing",
  "term_sheets": [
    {
      "unit_price": 132.0,
      "effective_date": "2027-04-01",
      "payment_days": 14
    },
    {
      "unit_price": 131.25,
      "effective_date": "2027-01-01",
      "payment_days": 14
    }
  ],
  "rationale": "Their April alternative now slightly improves total cost and preserves a higher ongoing supplier price, making it the stronger route to explore. Smaller conditional concessions seek further movement without surrendering the remaining gap.",
  "target_price": 132.0
}

