{
  "action": "send",
  "subject": "HN casings – final implementation adjustment",
  "body": "Dear Mr Brandlhuber,\n\nThank you for accepting our January package and confirming the annual quantity reconciliation. We appreciate your constructive cooperation.\n\nBefore we issue the order, could we make one final exchange? We can increase the unit price to €131.40 if you defer implementation to 1 April 2027, with existing pricing continuing beforehand. Payment would remain 14 days net and all fixed enquiry terms would remain unchanged.\n\nThis gives you a higher ongoing unit price while providing us the transition period we preferred. If that exchange is not workable, we are ready to conclude on the January package you have accepted.\n\nKind regards,\nHollerau Pumpenwerke, Purchasing",
  "term_sheets": [
    {
      "unit_price": 131.4,
      "effective_date": "2027-04-01",
      "payment_days": 14
    }
  ],
  "rationale": "They accepted the January alternative rather than the preferred April package. This final test offers a small real price give-back in exchange for delayed implementation, improving total cost while preserving the accepted agreement if declined.",
  "target_price": 131.4
}

